  'role.greeter': "ہوسٹ", 'opt.tickets': "ٹکٹ کہاں ملیں گے؟", 'opt.tonight': "آج کیا اچھا ہے؟", 'gre.hello': ["لومیئر میں خوش آمدید! سیڑھی کا دھیان رکھیے، یہ ریڈ کارپٹ فلموں سے زیادہ لوگوں کو گراتا ہے۔", "آئیے، آئیے! ٹکٹ اندر بائیں طرف ہیں، پاپ کارن دائیں طرف، اور خوشی ہر طرف۔", "ہیلو، ہیلو! پہلی بار آئے ہیں؟ آپ کو بہت مزہ آئے گا۔ یہاں کی سیٹیں میرے بستر سے بھی نرم ہیں۔", "خوش آمدید! فون سائلنٹ پر، پاؤں سیٹوں سے نیچے، اور امیدیں بہت، بہت اونچی۔", "ارے، فلموں کے شوقین! اندر آئیے، اندر آئیے۔ آج کی شام اب اور بھی اچھی ہوگی۔"], 'gre.bark': ["لومیئر میں خوش آمدید!", "ٹکٹ اندر، بائیں طرف!", "شام کا مزہ لیجیے!", "سیڑھی کا دھیان رکھیے، اسے ٹخنے بہت پسند ہیں۔"], 'gre.greet': ["ہائے! میں کلارا ہوں۔ جادو شروع ہونے سے پہلے کوئی مدد چاہیے؟", "پھر سے ہیلو! کھو گئے؟ اچھے اچھوں کے ساتھ ہوتا ہے۔", "راستہ، کوئی مشورہ، یا بس ایک مسکراتا چہرہ؟ میں تینوں دیتی ہوں۔"], 'gre.tickets': ["ٹکٹ کاؤنٹر سیدھے اندر، بائیں طرف ہے۔ ایلوئیز سے ملیے، وہ کبھی پلک نہیں جھپکاتی۔", "اندر، بائیں طرف، چمکتے بورڈ کے نیچے۔ اگر پاپ کارن تک پہنچ گئے، تو آپ دائیں طرف مڑ گئے۔ مزےدار غلطی۔", "ٹکٹ ایلوئیز کے پاس ہیں، ٹکٹ کاؤنٹر پر۔ پیسے کم ہیں؟ اے ٹی ایم یہیں باہر، دروازوں کے پاس ہے۔"], 'gre.tonight': ["آج سنٹیل لگی ہے۔ ایک لڑکی، ایک چھوٹا سا ڈریگن، اور اتنے آنسو کہ ہمارے ٹشو کم پڑ جائیں۔", "ہنسنا ہے؟ بگ بک بنی۔ سوچنا ہے؟ کاسموس لانڈرومیٹ۔ دونوں؟ دو ٹکٹ لے لیجیے۔", "ایجنٹ تھری ٹو سیون میں بس گھونسے اور ہیئر اسپرے ہیں۔ میری پسندیدہ۔ مینیجر کو مت بتائیے گا۔"], 'gre.where': ["واش روم کوریڈور کے آخر میں ہیں، اسکرینوں کے آگے۔ اے ٹی ایم یہیں باہر ہے۔", "اسنیکس؟ بس اپنی ناک کے پیچھے چلیے۔ پاپ کارن کی خوشبو کا اپنا ہی پتہ ہے۔"], 'rec.again': ["آپ کے پاس ٹکٹ تو ہے۔ اسکرین کے پاس مارسیل کو دکھائیے، وہ آپ کو سیٹ تک لے جائے گا۔", "پھر آ گئے؟ آپ کا ٹکٹ اب بھی چلے گا۔ مارسیل اسکرینوں کے پاس انتظار کر رہا ہے۔", "ٹکٹ آپ کی جیب میں ہے۔ فلم ہمیشہ انتظار نہیں کرے گی، اور مارسیل بھی نہیں۔", "کچھ اور چاہیے؟ آپ کی سیٹ بک ہے۔ آگے مارسیل سنبھال لے گا۔"], 'rec.tablet': ["یہ لیجیے ٹیبلٹ۔ آپ کے سارے ویڈیو اس میں ہیں۔ ایک چنیے، پھر واپس دے دیجیے۔", "ٹیبلٹ ایک منٹ کے لیے آپ کا۔ ویڈیو چنیے، باقی میں دیکھ لوں گی۔", "چلیے، اسکرول کیجیے۔ چننے میں سب بہت وقت لیتے ہیں۔ میں ایسے دکھاؤں گی جیسے دیکھ نہیں رہی۔"], 'bar.give': ["مزے لیجیے۔ یہ دکھنے سے بھی اچھا ہے، اور دکھتا بھی کمال ہے۔", "یہ لیجیے۔ کپ ری سائیکل ہو جاتا ہے، یادیں نہیں۔", "سب آپ کا۔ مارسیل پر مت گرائیے گا، اس کی ہر چیز پر نظر رہتی ہے۔"], 'srv.tablet': ["یہ رہا ٹیبلٹ۔ اسکرین پر ٹیپ کیجیے، چالو ہو جائے گا۔","شو کے دوران یہ آپ کا ہے۔ اس سے آرڈر بھی کر سکتے ہیں، اور اپنے ویڈیو بھی چلا سکتے ہیں۔"], 'srv.handBack': ["شکریہ۔ جو ایکسٹرا ہے، وہ آپ کے بل میں جڑ جائے گا۔", "ٹھیک ہے۔ میں چپ چاپ چلتا ہوں۔"],
